import{St as e,at as t,et as n,it as r,n as i,ot as a,rt as o,vt as s}from"./chunks/framework.CoUqiBXn.js";var c=JSON.parse(`{"title":"FAQs for using SysReptor","description":"","frontmatter":{},"headers":[],"relativePath":"faq/application.md","filePath":"faq/application.md","lastUpdated":1789544512000}`),l={name:`faq/application.md`},u={class:`info custom-block`},d={class:`custom-block-title`};function f(i,c,l,f,p,m){let h=e(`FaqExpandAll`),g=e(`DocBadge`);return s(),o(`div`,null,[c[1]||=r(`<h1 id="faqs-for-using-sysreptor" tabindex="-1">FAQs for using SysReptor <a class="header-anchor" href="#faqs-for-using-sysreptor" aria-label="Permalink to “FAQs for using SysReptor”">​</a></h1><p>These FAQs cover the SysReptor application itself: writing reports, designs, API, MFA, and licensing. They apply to self-hosted, Cloud, and SysReptor Labs.</p><p>Designer HTML/CSS snippets are in the <a href="/designer/faqs">report design FAQs</a>. Install and ops questions are in <a href="/faq/self-hosted">self-hosted</a> or <a href="/faq/cloud">cloud</a>. Exam students: <a href="/faq/exam-reports">exam report FAQs</a>.</p>`,3),a(h),c[2]||=r(`<div class="faq-item"><details class="details custom-block"><summary>What is your release cycle?</summary><p>We aim to release <strong>every two weeks</strong>, usually on <strong>Wednesdays</strong>. Releases include new features, improvements, and bug fixes.</p><p>The schedule is not fixed. We ship sooner for urgent bugs or security issues, and later when a change needs more testing. Releases can also land on another weekday.</p></details></div><div class="faq-item"><details class="details custom-block"><summary>Where can I find the SysReptor changelog?</summary><p>Find out changelog on <a href="https://github.com/syslifters/sysreptor/releases" target="_blank" rel="noreferrer">GitHub</a>.<br> SysReptor installations with outbound connection to the Internet also receive update notifications with links to the latest release and changelog.</p></details></div><div class="faq-item" id="vdp"><details class="details custom-block"><summary>Do you have a vulnerability disclosure process?</summary><p>Yes. See the <a href="https://handbook.syslifters.com/vulnerability-disclosure" target="_blank" rel="noreferrer">Syslifters vulnerability disclosure policy</a>.</p></details></div><div class="faq-item" id="docx"><details class="details custom-block"><summary>Can I export a SysReptor report as DOCX?</summary><p>No. SysReptor does <strong>not</strong> export Microsoft Word (<code>.docx</code>) files.</p><p>SysReptor renders pentest reports as <strong>PDF</strong> from the project’s publish page. You can also:</p><ul><li><strong>Export a project</strong> as a SysReptor <code>.tar.gz</code> archive (for backup or import into another instance)</li><li>On <strong>self-hosted</strong> SysReptor, enable the <a href="https://github.com/Syslifters/sysreptor/tree/main/plugins/markdownexport" target="_blank" rel="noreferrer">markdownexport</a> plugin to export Markdown in a ZIP</li></ul></details></div><div class="faq-item"><details class="details custom-block"><summary>Where can I find the SysReptor API documentation?</summary><p>SysReptor’s HTTP API is documented in the <a href="https://demo.sysre.pt/api/public/utils/swagger-ui/" target="_blank" rel="noreferrer"><strong>Swagger UI</strong></a> on each instance.</p><p>For scripting and automation, we recommend the <a href="/python-library/"><code>reptor</code> Python library</a> or the <a href="/cli/getting-started"><code>reptor</code> CLI</a> instead of calling the HTTP API directly.</p></details></div><div class="faq-item"><details class="details custom-block"><summary>Why do I have no permissions in the SysReptor report designer?</summary><p>Editing <strong>global</strong> report designs requires the <strong>Designer</strong> permission. Users without it cannot change shared designs used by others.</p><p>Without Designer permission you still have read access to non-private designs. If <a href="/setup/configuration#private-designs">private designs</a> are enabled, you can create private designs that other users cannot see by default.</p><p>To change how <strong>one project&#39;s</strong> design, use <strong>Customize Design</strong> on the <strong>Publish</strong> page of that project. This does not require <strong>Designer</strong> permissions.</p><p>See <a href="/designer/designer">Designs</a> and <a href="/users/user-permissions#template-editor">User permissions</a>.</p></details></div><div class="faq-item"><details class="details custom-block"><summary>I updated the report design but in my project I don&#39;t see the changes. Why?</summary><p>A SysReptor pentest project does <strong>not</strong> keep a live link to the global design you picked at creation time. Creating a project <strong>copies</strong> the design into a project-specific snapshot. Later edits to the original design under <strong>Designs</strong> are not applied automatically to existing projects.</p><p>You edited the <strong>global</strong> design, but the project still uses its <strong>snapshot</strong>? To apply the newest global design, go to <strong>Settings</strong> in your project, use the <strong>Design</strong> drop-down to select your global design and save.</p><p>If field definitions differ, SysReptor warns that converting might lose data. You can force-change the design or duplicate the project first.</p></details></div><div class="faq-item"><details class="details custom-block"><summary>Why do I have no permissions in SysReptor finding templates?</summary><p>Creating and editing <strong>finding templates</strong> requires the <strong>Template Editor</strong> permission. Users without it cannot change templates used by others.</p><p>Without Template Editor permission you still have <strong>read access</strong> and can apply templates when writing findings. See <a href="/finding-templates/overview">Templates</a> and <a href="/users/user-permissions#template-editor">User permissions</a>.</p></details></div><div class="faq-item"><details class="details custom-block"><summary>Is SysReptor free or paid only?</summary><p>Large parts of SysReptor are free to use (SysReptor Community). We aim for a free and fully functional reporting tool for freelancers and small teams. We don&#39;t add restrictions that prevent commercial usage (such as watermarks, lack of customizations, etc.).</p><ul><li><strong>SysReptor Community</strong> is free to <a href="/setup/installation">self-host</a>. Some <a href="https://sysreptor.com/pricing" target="_blank" rel="noreferrer">features and multi-user roles require Professional</a>.</li><li><strong>SysReptor Professional</strong> is <a href="https://sysreptor.com/pricing" target="_blank" rel="noreferrer">paid</a> (self-hosted license or Cloud).</li><li><strong>SysReptor Labs</strong> at <a href="https://labs.sysre.pt" target="_blank" rel="noreferrer">labs.sysre.pt</a> for <a href="https://htb.sysreptor.com/htb/signup/" target="_blank" rel="noreferrer">HTB</a>/<a href="https://offsec.sysreptor.com/offsec/signup/" target="_blank" rel="noreferrer">OffSec</a> students is <strong>free</strong> and includes Pro features. See <a href="/faq/exam-reports">exam report FAQs</a>.</li></ul></details></div><div class="faq-item" id="mfa"><details class="details custom-block"><summary>How do I add 2FA/MFA for a SysReptor user?</summary><p>On any SysReptor instance, open <strong>your user profile → Security</strong> (<code>/users/self/security/</code>) and add a method:</p><ul><li><strong>Security key (FIDO2 / WebAuthn)</strong></li><li><strong>Authenticator app (TOTP)</strong></li><li><strong>Backup codes</strong> (store them offline)</li></ul><p>You can set a primary method. Superusers or user managers can remove all MFA devices for a user who is locked out (<code>/users/&lt;user-id&gt;/mfa/</code>).</p><p>On <strong>self-hosted</strong> SysReptor, FIDO2 requires <code>MFA_FIDO2_RP_ID</code> set to your hostname. See <a href="/setup/configuration#fido2webauthn">Configuration</a>.</p><p>We highly recommend adding MFA for every user account.</p></details></div><div class="faq-item"><details class="details custom-block"><summary>How do I write re-test reports in SysReptor?</summary><p>You can write your retest notes directly to your existing project.<br> To keep the original report unchanged, <strong>duplicate</strong> the project and add re-test notes in the copy.</p><p>We recommend adding the predefined report field <strong><code>is_retest</code></strong> and finding fields <strong><code>retest_status</code></strong> and <strong><code>retest_notes</code></strong> to the design.</p><ol><li>Add those fields to the design if they are not already there.</li><li>Set <strong>Is Retest</strong> to true on the project you use for the re-test.</li><li>Update each finding’s re-test status (Open, Resolved, Partially Resolved, Changed, Accepted, New). Status colors appear in the report sidebar when the design includes <code>retest_status</code>.</li><li>In the PDF design, show retest-only blocks with Vue, for example <code>v-if=&quot;report.is_retest&quot;</code>. See <a href="/designer/designer">Report designer</a>.</li></ol></details></div><div class="faq-item"><details class="details custom-block"><summary>How do I export a SysReptor report as PDF?</summary><p>Open the pentest project’s <strong>publish</strong> page, preview the PDF, then use <strong>Download</strong>. You can set a filename and an optional PDF password.</p></details></div><div class="faq-item"><details class="details custom-block"><summary>How do I export or import a SysReptor pentest project?</summary><p>On the <strong>Projects</strong> list, select one or more projects and export a <code>.tar.gz</code> archive (with or without notes). Import uses the import button on the same list.</p><p>Project export does <strong>not</strong> include the <a href="/reporting/version-history">version history</a> and <a href="/reporting/comments-and-review#comments">comments</a>.</p></details></div>`,13),n(`div`,u,[n(`p`,d,[a(g,{icon:`mdi:help-circle`,class:`lg middle`,label:`Further questions?`})]),c[0]||=n(`p`,null,[t(`Need help or have questions? Get support and `),n(`a`,{href:`https://github.com/Syslifters/sysreptor/discussions/`,target:`_blank`,rel:`noreferrer`},`connect with us and the SysReptor community`),t(`.`)],-1)])])}var p=i(l,[[`render`,f]]);export{c as __pageData,p as default};